<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Status from '../components/common/Status.vue';import Empty from '../components/common/Empty.vue';import RankingTable from '../components/RankingTable.vue';import WeightBars from '../components/WeightBars.vue';import DistancePlot from '../components/DistancePlot.vue';import SensitivityChart from '../components/SensitivityChart.vue';import JudgmentGrid from '../components/JudgmentGrid.vue';import {number} from '../utils/format';const props=defineProps<{data:Workspace}>();const selected=ref('');const run=computed(()=>props.data.runs.find(r=>r.id===selected.value)||props.data.runs[0]);</script><template><PageHeading code="05 / RANK & SENSITIVITY" title="先看一致性，再看名次能否站住。" description="高CR警告不被隐藏。无辨识力的指标或距离退化不硬排名，扰动范围不等于概率。"/><div class="run-selector"><label>计算记录<select aria-label="选择计算记录" :value="run?.id" @change="selected=($event.target as HTMLSelectElement).value"><option v-for="r in data.runs" :key="r.id" :value="r.id">{{data.judgments.find(j=>j.id===r.judgment_id)?.name}} · {{r.created_at.slice(11,19)}} · v{{r.result?.version?.version_no ?? '—'}}</option></select></label><Status v-if="run" :value="run.status"/><span class="version-badge" v-if="run?.result?.version">钉住快照 v{{run.result.version.version_no}} · 发起时口径冻结</span></div><Empty v-if="!run">先保存指标方向和原始判断矩阵，再运行后台权衡。</Empty><Notice v-else-if="run.status!=='completed'" :error="run.status==='failed'">{{run.status==='failed'?run.error:'独立worker正在计算，页面会自动刷新。'}}</Notice><template v-else><Notice v-if="run.result.ahp.cr_warning" error>CR={{number(run.result.ahp.cr,4)}}高于声明阈值{{number(run.result.ahp.threshold,2)}}。原矩阵完整保留，请复核循环矛盾；系统没有自动改值。</Notice><section class="paper"><div class="section-heading"><h2>AHP主特征向量与一致性</h2><span>幂迭代{{run.result.ahp.iterations}}次 / RI={{number(run.result.ahp.ri,2)}}</span></div><div class="result-metrics"><div><small>主特征值 λmax</small><b>{{number(run.result.ahp.lambda_max,4)}}</b></div><div><small>一致性指标 CI</small><b>{{number(run.result.ahp.ci,4)}}</b></div><div :class="{warning:run.result.ahp.cr_warning}"><small>一致性比率 CR</small><b>{{number(run.result.ahp.cr,4)}}</b></div><div><small>声明阈值</small><b>{{number(run.result.ahp.threshold,2)}}</b></div></div><WeightBars :criteria="run.result.criteria" :weights="run.result.ahp.weights"/><p class="caption">RI表：3=.58 / 4=.90 / 5=1.12 / 6=1.24。阈值只是讨论规则；特征残差{{run.result.ahp.eigen_residual.toExponential(2)}}。</p></section><Notice v-if="!run.result.topsis.available" error>{{run.result.topsis.reason}}<ul><li v-for="issue in run.result.topsis.issues" :key="issue.criterion_index">{{run.result.criteria[issue.criterion_index]?.label}}：{{issue.reason}}</li></ul></Notice><section class="paper"><h2>TOPSIS方案排序</h2><RankingTable :rows="run.result.alternatives"/></section><div class="evidence-grid" v-if="run.result.topsis.available"><section class="paper"><h2>到优、劣理想点的距离</h2><DistancePlot :rows="run.result.alternatives"/></section><aside class="definition-note"><span class="eyebrow">IDEAL POINT DISTANCE</span><h2>离优点更近，<br/>离劣点更远。</h2><p>列向量归一后按AHP权重加权。成本指标以最小值为优点，收益指标以最大值为优点。</p><p>贴近度 = 到劣点距离 /（到优点距离 + 到劣点距离）。并列贴近度保留并列名次。</p></aside></div><section class="paper" v-if="run.result.sensitivity.length"><div class="section-heading"><h2>单权重扰动的名次范围</h2><span>逐指标±{{Math.round(run.result.perturbation*100)}}% / {{run.result.sensitivity.length}}个确定性情景</span></div><SensitivityChart :rows="run.result.alternatives"/><p class="caption">线段为情景最小—最大名次，点为基准名次；每次只改一个权重，再把全部权重归一。不是联合扰动或概率区间。</p></section><section class="paper"><h2>保存的原始判断矩阵</h2><JudgmentGrid :matrix="run.result.matrix_original" :criteria="run.result.criteria"/></section><aside class="assumptions"><h2>判断规则与解释边界</h2><p v-for="(a,i) in run.result.assumptions" :key="a"><b>0{{i+1}}</b>{{a}}</p><small>输入校验码 {{run.result.checksum.slice(0,24)}}</small></aside></template></template>
